#pragma once
// Boiler fault descriptions (PDU 2100), English and Italian.
// Source: Immergas Dominus app 2.3.1, anomalies[] (EN = text1. comment -> action as in the original
// YAML; IT = text1-it. comment-it -> action-it). Format "title. description -> action", fitted to
// HA's 255-char state limit by shortening the description first, so title and action survive.
#include <cstring>
#include <string>

namespace faults {

struct Entry {
  int code;
  const char *en;
  const char *it;
};

static const Entry TABLE[] = {
    {0, "SYSTEM OK. No anomaly -> No action required",
         "SISTEMA OK. Nessuna anomalia -> Nessuna azione richiesta"},
    {1, "No ignition block. In the event of request of room central heating or domestic hot water production, the boiler does not switch on within the preset time. Upon appliance commissioning or after extended downtime, it may be necessary to eliminate the block. -> Press the Reset button",
         "Blocco mancata accensione. La caldaia in caso di richiesta di riscaldamento ambiente o produzione acqua calda sanitaria non si accende entro il tempo prestabilito. Alla prima accensione o dopo prolungata inattivita' dell'apparecchio puo' essere necessario intervenire per eliminare il blocco. -> Premere il pulsante di Reset"},
    {2, "Safety thermostat block (over-temperature). During normal operation, if a fault causes excessive overheating internally, the boiler goes into overheating block. -> Press the Reset button",
         "Blocco termostato sicurezza (sovratemperatura). Durante il normale regime di funzionamento se per un'anomalia si verifica un eccessivo surriscaldamento interno la caldaia va in blocco. -> Premere il pulsante di Reset"},
    {3, "Flue safety thermostat block. During normal operation, if a fault causes excessive flue gas overheating, the boiler blocks. (Nike versions)/ Wrong P.14 parameter configuration (Star version) -> Press the Reset button (Nike versions)/ Correctly configure the P.14 parameter. Press the Reset button if required (Star versions)",
         "Blocco termostato fumi. Durante il normale regime di funzionamento se per un'anomalia si verifica un eccessivo surriscaldamento dei fumi la caldaia va in blocco (versioni Nike)/ Configurazione errata parametro P.14 (versione Star) -> Premere il pulsante di Reset (versioni Nike)/ Configurare correttamente il parametro P.14. Se necessario premere il pulsante di Reset (versioni Star)"},
    {4, "Contacts resistance block. The P.C.B. detects an anomaly on the gas valve supply. Check the connection. (the anomaly is detected and displayed only in the event of a request). -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Blocco resistenza contatti. La scheda elettronica rileva un'anomalia sull'alimentazione della valvola gas. Verificare il collegamento della stessa. (l'anomalia viene rilevata e visualizzata solo in presenza di una richiesta). -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)"},
    {5, "Flow probe anomaly. The P.C.B. detects an anomaly on the flow NTC probe. -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Anomalia sonda mandata. La scheda rileva un'anomalia sulla sonda NTC mandata. -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)"},
    {6, "Domestic hot water probe anomaly. The P.C.B. detects an anomaly on the domestic hot water NTC probe. -> In this case the boiler continues to produce domestic hot water but not with optimal performance. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Anomalia sonda sanitario. La scheda rileva un'anomalia sulla sonda NTC sanitario. -> La caldaia continua a produrre acqua calda sanitaria ma con prestazioni non ottimali. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)"},
    {8, "Maximum N° of reset. Number of allowed resets that have already performed. -> Attention: the anomaly can be reset 5 times consecutively, after which the function in inhibited for at least one hour. One attempt is gained every hour for a maximum of 5 attempts. By switching the appliance on and off again, the 5 attempts are re-acquired.",
         "Numero massimo di reset. Numero di reset disponibili gia' eseguiti. -> Attenzione: e' possibile resettare l'anomalia fino a 5 volte consecutive, dopodiche' la funzione e' inibita per almeno un'ora e si guadagna un tentativo ogni ora per un massimo di 5 tentativi. Togliendo e riapplicando l'alimentazione all'apparecchio si riacquistano i 5 tentativi."},
    {10, "Insufficient system pressure. Water pressure inside the central heating circuit that is sufficient to guarantee the correct operation of the boiler is not detected. -> Check on the boiler pressure gauge that the system pressure is between 1÷1.2 bar and restore the correct pressure if necessary.",
         "Pressione impianto insufficiente. Non viene rilevata una pressione dell'acqua all'interno del circuito di riscaldamento sufficiente per garantire il corretto funzionamento della caldaia. -> Verificare sul manometro di caldaia che la pressione dell'impianto sia compresa tra 1÷1,2 bar ed eventualmente ripristinare la corretta pressione."},
    {11, "Flue pressure switch anomaly. If normal conditions are restored the boiler restarts without having to be reset -> If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service)",
         "Anomalia pressostato fumi. Se le condizioni normale di funzionamento vengono ripristinate la caldaia riparte senza la necessità di essere resettata -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)"},
    {12, "Storage tank probe anomaly. If the P.C.B. detects a fault in the boiler probe, the boiler cannot produce DHW and signals a fault. -> The boiler does not satisfy the DHW production requests. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Anomalia sonda boiler. La scheda rileva un'anomalia sulla sonda boiler -> La caldaia non puo' produrre acqua calda sanitaria. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)"},
    {13, "Air/flue gas flow-meter out of range. With fan stopped, the air/flue gas controller reads an excessively high signal (pressure switch contacts stuck) -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Misuratore portata aria/fumi fuori range. Con ventilatore fermo, il controllo aria/fumi legge un segnale troppo alto(contatti pressostato incollati) -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {15, "Configuration error. If the P.C.B. detects an anomaly or incongruity on the electric wiring, the boiler will not start. -> If normal conditions are restored the boiler restarts without having to be reset. Check that the boiler is configured correctly. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Errore configurazione. La scheda rileva un'anomalia o un incongruenza sul cablaggio elettrico di caldaia e non parte. -> In caso di ripristino delle condizioni normali la caldaia riparte senza il bisogno di dover essere resettata. Verificare che la caldaia sia configurata in modo corretto. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)"},
    {16, "Fan anomaly. This occurs if the fan has a mechanical or electrical fault. -> Press the Reset button. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Anomalia ventilatore. Si verifica nel caso in cui il ventilatore abbia un guasto meccanico o elettronico. -> Premere il pulsante di Reset. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)"},
    {17, "Incorrect fan speed. Number of fan revolutions incorrect -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Velocità ventilatore non corretta. Numero di giri ventilatore non corretto -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {20, "Parasite flame block. This occurs in the event of a leak on the detection circuit or anomaly in the flame control unit. -> Press the Reset button. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Blocco fiamma parassita. Si verifica in caso di dispersione nel circuito di rilevazione o anomalia nel controllo fiamma. -> Premere il pulsante di Reset. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)"},
    {23, "Return probe anomaly. The P.C.B. detects an anomaly on the flow NTC probe. -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Anomalia sonda ritorno. La scheda rileva un'anomalia sulla sonda NTC mandata. -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)"},
    {24, "Push button control panel anomaly. The P.C.B. detects an anomaly on the pushbutton panel. -> If normal conditions are restored the boiler restarts without having to be reset. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Anomalia pulsantiera. La scheda rileva un'anomalia sulla pulsantiera. -> In caso di ripristino delle condizioni normali la caldaia riparte senza il bisogno di dover essere resettata. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)"},
    {25, "Flue probe block / CRC block (TERA). High flue gas gradient, probable circulator block or no water / memory corrupted -> Press the Reset button",
         "Blocco sonda fumi / blocco CRC (TERA). Gradiente fumi elevato, probabile blocco circolatore o mancanza acqua / memoria corrotta -> Premere il pulsante di Reset"},
    {27, "Insufficient circulation. X -> Press the Reset button",
         "Circolazione insufficiente. Verificare che non siano presenti intercettazioni sul circuito di riscaldamento e/o verificare il corretto funzionamento del circolatore -> Premere il pulsante di Reset"},
    {28, "Domestic hot water leakage. Check that all domestic hot water system cocks are closed and are not leaking and also check that there are no leaks in the system. Once good conditions are restored in the domestic hot water system, the boiler returns to normal operation -> If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service)",
         "Trafila circuito sanitario. Controllare che tutti i rubinetti dell’impianto sanitario siano chiusi o che non trafilino, e comunque verificare che non ci siano perdite nell’impianto. La caldaia torna al normale funzionamento una volta ripristinate le condizioni ottimali sull’impianto sanitario -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)"},
    {29, "Flue probe anomaly. The P.C.B. detects an anomaly on the flue gas probe. -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Anomalia sonda fumi. La scheda rileva un'anomalia sulla sonda fumi. -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)"},
    {31, "Loss of communication with the CARV2. This occurs if an incompatible remote control is connected, or if communication between the boiler and CARV2 is lost. -> Power cycle the boiler. If the Remote Control is still not detected on re-starting the boiler will switch to local operating mode, i.e. using the controls on the control panel. In this case the \"Central Heating\" mode cannot be activated.",
         "Perdita di comunicazione col CARV2. Si verifica nel caso di collegamento a un controllo remoto non compatibile, oppure in caso di caduta di comunicazione fra caldaia e CARV2. -> Togliere e ridare tensione alla caldaia. Se alla riaccensione non viene rilevato il Comando Remoto la caldaia passa in modalita' di funzionamento locale quindi utilizzando i comandi presenti sul pannello comandi. In questo caso non e' possibile attivare la funzione \"Riscaldamento\"."},
    {32, "Zone 2 low temperature probe anomaly. If the board detects an anomaly on the zone 2 low temperature probe, the system cannot work in the affected area -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Anomalia sonda Zona 2 bassa temperatura. La scheda rileva un’anomalia sulla sonda zona 2 bassa temperatura il sistema non può funzionare nella zona interessata -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {33, "Zone 3 low temperature probe anomaly. If the board detects an anomaly on the zone 2 low temperature probe, the system cannot work in the affected area -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Anomalia sonda Zona 3 bassa temperatura. La scheda rileva un’anomalia sulla sonda zona 2 bassa temperatura il sistema non può funzionare nella zona interessata -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {36, "IMG Bus communication loss. Communication between the various components is interrupted due to an anomaly on the boiler control unit, on the zone control unit or on the IMG Bus. -> The boiler does not satisfy the room heating requests.",
         "Caduta comunicazione IMG Bus. A causa di un anomalia sulla centralina di caldaia, sulla scheda a zone (optional) o sull'IMG Bus si interrompe la comunicazione tra i vari componenti. -> La caldaia non soddisfa le richieste di riscaldamento."},
    {37, "Low power supply voltage. This occurs when the power supply voltage is lower than the allowed limits for the correct boiler operation. -> If normal conditions are restored the boiler restarts without having to be reset.",
         "Bassa tensione di alimentazione. Si verifica nel caso in cui la tensione di alimentazione e' inferiore ai limiti consentiti per il corretto funzionamento della caldaia. -> In caso di ripristino delle condizioni normali la caldaia riparte senza il bisogno di dover essere resettata."},
    {38, "Loss of flame signal. This occurs when the boiler is ignited correctly and the burner flame switches off unexpectedly; a new attempt at ignition is performed and if normal conditions are restored, the boiler does not have to be reset. -> If normal conditions are restored the boiler restarts without having to be reset.",
         "Perdita segnale di fiamma. Si verifica nel caso in cui la caldaia e' accesa correttamente e avviene uno spegnimento inaspettato della fiamma del bruciatore; viene eseguito un nuovo tentativo di riaccensione e in caso di ripristino delle normali condizioni la caldaia non necessita di essere resettata. -> In caso di ripristino delle condizioni normali la caldaia riparte senza il bisogno di dover essere resettata."},
    {39, "Solar collector probe anomaly. If the board detects an anomaly on the solar collector probe, the boiler continues to work regularly without the intake of solar energy for heating the DHW as the solar pump stops working -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "anomalia sonda collettore solare. La scheda rileva un’anomalia sulla sonda collettore solare, la caldaia continua a funzionare regolarmente senza l’apporto di energia solare per il riscaldamento dell’acqua calda sanitaria in quanto la pompa solare smette di funzionare -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {40, "Solar storage tank probe anomaly. If the board detects a fault on the solar storage tank probe, the boiler continues to work regularly without the intake of solar energy for heating the DHW as the solar pump stops working. -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Anomalia sonda accumulo solare. La scheda rileva un’anomalia sulla sonda accumulo solare, la caldaia continua a funzionare regolarmente senza l’apporto di energia solare per il riscaldamento dell’acqua calda sanitaria in quanto la pompa solare smette di funzionare. -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {41, "High temperature on the solar collector. This occurs when the temperature of the solar collector exceeds the maximum limit set -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Temperatura elevata su collettore solare. Si verifica quando la temperatura del collettore solare supera il limite massimo impostato -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {42, "High temperature on the solar storage tank. This occurs when the temperature of the water in the solar storage tank exceeds the maximum limit set. -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Temperatura elevata su accumulo solare. Si verifica quando la temperatura dell’acqua nell'accumulo solare supera il limite massimo impostato. -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {43, "Block due to loss of flame signal. This occurs if the \"Flame signal loss\" error occurs many times in a row within a preset period. -> Press the Reset button, before restarting, the boiler will run a post-ventilation cycle.",
         "Blocco per perdita segnale di fiamma. Si verifica se si presenta per più volte consecutive nell'arco di un tempo prestabilito l'errore \"Perdita segnale di fiamma\". -> Premere il pulsante di Reset, la caldaia prima di ripartire effettua un ciclo di postventilazione."},
    {44, "Block for exceeding the maximum accumulated time, close gas valve opening. This occurs if the gas valve remains open for longer than required for normal operation, without the boiler switching on. -> Press the Reset button.",
         "Blocco per superamento accumulo tempo massimo aperture ravvicinate valvola gas. Si verifica nel caso in cui la valvola gas rimane aperta per un tempo superiore a quello previsto per il suo normale funzionamento senza che la caldaia si accenda. -> Premere il pulsante di Reset."},
    {45, "dT high. The boiler detects a sudden, unexpected increase in the dT between the flow probe and the system return probe. -> The power of the burner is limited to prevent damage to the condensation module and once the right dT is restored, the boiler resumes regular operation. Make sure there is water circulating in the boiler, that the pump is configured according to system requirements and that the return probe works properly.",
         "dT elevato. La caldaia rileva un innalzamento improvviso e non previsto del dT tra sonda mandata e sonda ritorno impianto. -> Viene limitata la potenza del bruciatore per prevenire eventuali danni al modulo a condensazione, una volta ripristinato il giusto dT la caldaia torna al normale funzionamento. Verificare che ci sia circolazione di acqua in caldaia, che il circolatore sia configurato secondo le esigenze dell'impianto e il corretto funzionamento della sonda di ritorno."},
    {46, "Low temperature thermostat intervention / Incorrect wiring/board configuration. During normal operation, if an anomaly causes excessive overheating of the flow temperature in low temperature conditions, the boiler shuts down. / Wiring error or use of incorrect spare board -> In this case, after cooling down, it is possible to reset the thermostat (see relative instruction sheet). / If the blockage or anomaly persists it is necessary to call an authorised company (e.g. Immergas Technical Assistance Service).",
         "Intervento termostato bassa temperatura / Errata configurazione cablaggio/scheda. Durante il normale regime di funzionamento se per un'anomalia si verifica un eccessivo surriscaldamento della temperatura di mandata in bassa temperatura la caldaia va in blocco. / Errore cablaggio o utilizzo scheda di ricambio errata -> In questo caso dopo un opportuno raffreddamento e' possibile resettare il termostato (vedi relativo foglio istruzioni). / Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {47, "Burner power limitation. Should flue high temperature be detected, the boiler reduces power supplied so as not to damage it. -> If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Limitazione potenza bruciatore. Nel caso in cui venga rilevata un'elevata temperatura fumi la caldaia riduce la potenza erogata per non danneggiare la stessa. -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {48, "System side flow probe anomaly. In the event that the system side flow probe is not connected or is faulty, the anomaly is indicated -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Anomalia sonda mandata lato impianto. In caso di sonda di mandata lato impianto non collegata o guasta viene segnalata l’anomalia -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {49, "High temperature block on return probe. This occurs when the heat exchanger return circuit reaches an excessively high temperature -> Make sure that water circulates properly in the boiler and that the three-way valve works properly.",
         "Blocco temperatura elevata su sond ritorno. Si verifica nel caso venga raggiunta una temperatura troppo alta sul circuito di ritorno scambiatore -> Verificare la corretta circolazione in caldaia e il buon funzionamento della valvola tre vie."},
    {50, "External probe anomaly. In the event that the external probe is not connected or is faulty, the anomaly is indicated -> Check the external probe connection. The system keeps working",
         "Anomalia sonda esterna. In caso di sonda esterna non collegata o guasta viene segnalata l’anomalia -> Verificare il collegamento della sonda esterna. Il sistema continua a funzionare"},
    {51, "CAR Wireless communication failure. If there is no communication between the boiler and Wireless version CAR, an anomaly is signalled. From this moment, it is only possible to control the system by means of the control panel of the boiler itself. -> Check operation of the Wireless CAR, check the battery charge (refer to the relative instructions booklet).",
         "Caduta comunicazione con CAR Wireless. In caso di caduta di comunicazione tra caldaia e CAR versione Wireless viene segnalata l'anomalia, da questo momento e' possibile controllare il sistema unicamente attraverso il pannello comandi della caldaia stessa. -> Verificare il funzionamento del CAR Wireless, verificare la carica delle batterie (vedere il relativo libretto istruzioni)."},
    {54, "Puffer probe anomaly. In the event that the puffer probe is not connected or is faulty, the anomaly is indicated -> The puffer mode is disabled",
         "Anomalia sonda puffer. In caso di sonda puffer non collegata o guasta viene segnalata l’anomalia -> La modalità puffer viene disabilitata"},
    {55, "Zone 1 flow temperature probe anomaly. If the board detects an anomaly on the zone 1 low temperature probe, the system cannot work in the affected area. -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Anomalia sonda temperatura mandata Zona 1. La scheda rileva un’anomalia sulla sonda zona 1 bassa temperatura il sistema non può funzionare nella zona interessata. -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {58, "Audax anomaly. Anomaly on the Audax heat pump, check the type of anomaly directly on the heat pump display -> The heat pump does not satisfy the room heating and cooling requests; once the connections are restored, switch the system on and off again",
         "Anomalia Audax. Anomalia sulla pompa di calore Audax, verificare il tipo di anomalia direttamente sul display della pompa di calore -> La pompa di calore non soddisfa le richieste di riscaldamento e raffrescamento ambiente, una volta ripristinati i collegamenti è necessario spegnere e riaccendere il sistema"},
    {59, "Main supply voltage frequency block. The P.C.B. detects a main supply voltage frequency anomaly. -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Blocco frequenza rete alimentazione elettrica. La scheda rileva una frequenza sull'alimentazione di rete elettrica anomala. -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {60, "Anomaly pump blocked. The pump is stopped due to one of the following causes: impeller blocked, electrical fault. -> Try to unblock the pump as described in the relative section. If normal conditions are restored the boiler restarts without having to be reset.",
         "Anomalia circolatore bloccato. Il circolatore risulta fermo per una delle seguenti cause: girante bloccata, guasto elettrico. -> Provare ad effettuare lo sblocco del circolatore come descritto nel relativo paragrafo. In caso di ripristino delle condizioni normali la caldaia riparte senza il bisogno di dover essere resettata."},
    {61, "Air in circulator pump. Air is detected inside the pump; the pump cannot work. -> Vent the pump and the central heating circuit. If normal conditions are restored the boiler restarts without having to be reset.",
         "Presenza aria nel circolatore. Viene rilevata aria all'interno del circolatore; il circolatore non puo' funzionare. -> Effettuare lo sfiato del circolatore e del circuito di riscaldamento. In caso di ripristino delle condizioni normali la caldaia riparte senza il bisogno di dover essere resettata."},
    {62, "Complete calibration required. Missing calibration is detected by the P.C.B. It may occur in the event the P.C.B. is replaced or if the parameters are altered in the air / gas section, thus requiring \"complete calibration\". -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Richiesta taratura completa. Viene rilevata l'assenza di taratura della scheda elettronica. Si puo' verificare in caso di sostituzione della scheda elettronica o in caso di variazione dei parametri nella sezione aria / gas per cui si rende necessaria la \"taratura completa\". -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {63, "System return probe anomaly. In the event that the return probe is not connected or is faulty, the anomaly is indicated -> The boiler continues to operate without any integration from the external systems connected",
         "Anomalia sonda ritorno impianto. In caso di sonda di ritorno non collegata o guasta viene segnalata l’anomalia -> La caldaia continua a funzionare senza nessuna integrazione dai sistemi esterni collegati"},
    {67, "Solar system pressure switch anomaly. Due to a pressure drop in the solar circuit, the pressure switch blocks the operation of the thermal solar circuit -> Check on the pressure gauge of the solar circulation unit that the pressure is at the correct value",
         "Anomalia pressostato impianto solare. A causa di un calo della pressione nel circuito solare il pressostato blocca il funzionamento del circuito solare termico -> Verificare sul manometro del gruppo di circolazione solare che la pressione sia ad al valore corretto"},
    {70, "Return/flow probe exchange. X -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Sonde invertite. Verificare il collegamento della sonda di mandata e di ritorno -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {72, "Fast calibration required. The P.C.B. detects that some parameters have been altered, thus requiring \"fast calibration\". -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Richiesta taratura veloce. Viene rilevata una modifica di alcuni parametri per cui si rende necessaria la \"taratura veloce\". -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {73, "High flow probe and safety flow probe deviation detected. The P.C.B. detects an anomaly in the temperature readings of the NTC flow probes; the causes may be: faulty probe, incorrect position, poor system circulation, or clogging of the water side primary heat exchanger. -> If normal conditions are restored the boiler restarts without having to be reset.",
         "Rilevato scostamento elevato sonda mandata e sonda mandata di sicurezza. La scheda rileva un'anomalia nella lettura delle temperature delle sonde NTC di mandata e le cause possono essere: sonda difettosa, posizionamento scorretto, scarsa circolazione impianto, intasamento lato acqua dello scambiatore primario. -> In caso di ripristino delle condizioni normali la caldaia riparte senza il bisogno di dover essere resettata"},
    {74, "Safety flow probe anomaly. The P.C.B. detects an anomaly on the NTC safety flow probe. -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Anomalia sonda mandata di sicurezza. La scheda rileva un'anomalia sulla sonda NTC mandata di sicurezza. -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {75, "Return and/or flow probe malfunction. X -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Blocco per sensore NTC danneggiato. Il sensore della sonda di sicurezza provoca un gradiente di temperatura elevato -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {76, "Return and/or flow probes temperature drift. X -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Deriva sonda mandata o sonda ritorno. Differenza maggiore rispetto a quello impostato fra sonda di mandata e ritorno in caso di richiesta di calore -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {77, "Combustion control anomaly. Out of range current is detected on the gas valve. -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Anomalia controllo combustione. Viene rilevata una corrente fuori range sulla valvola gas. -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {78, "Combustion control anomaly. High current on the gas valve is detected. -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Anomalia controllo combustione. Viene rilevata una corrente sulla valvola gas elevata. -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {79, "Combustion control anomaly. Reduced current on the gas valve is detected. -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Anomalia controllo combustione. Viene rilevata una corrente sulla valvola gas ridotta. -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {80, "P.C.B. malfunction block. This occurs in the event of malfunctions of the P.C.B. that controls the valve. -> Press the Reset button",
         "Blocco malfunzionamento scheda elettronica. Si verifica nel caso di malfunzionamento della scheda elettronica che controlla la valvola. -> Premere il pulsante di Reset"},
    {84, "Combustion anomaly - power reduction in progress. A low supply pressure is detected on the gas line. As a result the appliance power is limited and the anomaly is reported. -> If normal conditions are restored the boiler restarts without having to be reset",
         "Anomalia combustione - riduzione potenza in corso. Viene rilevata una bassa pressione di alimentazione sulla rete gas. Di conseguenza viene limitata la potenza dell'apparecchio e segnalata l'anomalia. -> In caso di ripristino delle condizioni normali la caldaia riparte senza il bisogno di dover essere resettata"},
    {85, "Afterburner problem block. Flame present for about after gas valve closing -> Press the Reset button. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Blocco problema post-combustione. Fiamma presente per circa dopo la chiusura della valvola gas -> Premere il pulsante di Reset. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)"},
    {87, "Block - gas valve control. A malfunction of one of the components that controls the gas valve has been detected. -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Blocco controllo valvola gas. Viene rilevato un malfunzionamento di uno dei componenti che controllano la valvola gas. -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {88, "Block - gas valve control. A malfunction of one of the components that controls the gas valve has been detected. -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Blocco controllo valvola gas. Viene rilevato un malfunzionamento di uno dei componenti che controllano la valvola gas. -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {89, "Combustion signal unstable. The flame is unstable due to: presence of flue gas recirculation, wind, unstable gas pressure, unstable fan speed, or due to system malfunction. -> The boiler keeps working.",
         "Segnale combustione instabile. La fiamma risulta essere instabile a causa di: presenza ricircolo fumi, vento, pressione gas instabile, velocita' ventilatore instabile oppure a causa di un malfunzionamento del sistema. -> La caldaia continua a funzionare."},
    {90, "Combustion signal beyond limit. The combustion signal is beyond the adjustment range required for an extended period of time. -> The boiler keeps working.",
         "Segnale combustione fuori limite. Il segnale di combustione viene rilevato fuori dal range di regolazione previsto per un tempo prolungato. -> La caldaia continua a funzionare."},
    {91, "Incorrect ignition block. The P.C.B. has exhausted all possible actions in order to obtain optimal ignition of the burner. -> Press the Reset button",
         "Blocco accensione non corretta. La scheda ha esaurito tutte le sue possibili azioni per ottenere un ottimale accensione del bruciatore. -> Premere il pulsante di Reset"},
    {92, "Fan revs correction limit. The system has exhausted all possible corrections of the number of fan revs. -> The boiler keeps working.",
         "Limite correzione giri ventilatore. Il sistema ha esaurito tutte le correzioni possibili del numero di giri del ventilatore. -> La caldaia continua a funzionare."},
    {93, "Combustion signal beyond limit. The combustion signal is beyond the adjustment range required for an extended period of time. -> The boiler keeps working.",
         "Segnale combustione fuori limite. Il segnale di combustione viene rilevato fuori dal range di regolazione previsto per un tempo prolungato. -> La caldaia continua a funzionare."},
    {94, "Combustion anomaly. A problem is detected on the combustion control, which may be due to: gas low pressure, flue recirculation, defective gas valve or P.C.B.. -> If normal conditions are restored the boiler restarts without having to be reset.",
         "Anomalia combustione. Viene rilevato un problema sul controllo combustione che puo' essere causato da: bassa pressione gas, ricircolo fumi, valvola gas o scheda elettronica difettosa. -> In caso di ripristino delle condizioni normali la caldaia riparte senza il bisogno di dover essere resettata."},
    {95, "Combustion signal discontinuous. The system detects a discontinuous combustion signal. -> The boiler keeps working.",
         "Segnale combustione discontinuo. Il sistema rileva una discontinuita' nel segnale di combustione. -> La caldaia continua a funzionare."},
    {96, "Clogged flue. This occurs in the event an obstruction is detected in the flue system. -> The boiler does not start. If the shutdown or fault persists, contact an authorised company (e.g. Authorised Technical After-Sales Service).",
         "Fumisteria ostruita. Si verifica nel caso venga rilevata un ostruzione nel sistema fumario. -> La caldaia non parte. Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {98, "Block - maximum no. of software errors. The maximum number of software errors possible has been reached. -> Press the Reset button",
         "Blocco n° massimo errori software. Viene raggiunto il numero massimo di errori software ammessi. -> Premere il pulsante di Reset"},
    {99, "General block. A boiler anomaly has been detected. -> Press the Reset button",
         "Blocco generico. Viene rilevata un'anomalia in caldaia. -> Premere il pulsante di Reset"},
    {101, "Audax off-line alarm. In the event of communication failure, incorrect connection or heat pump switched off, the boiler electronics do not detect the heat pump -> The heat pump does not satisfy the room heating and cooling requests; once the connections are restored, switch the system on and off again",
         "Allarme off-line Audax. Nel caso di caduta di comunicazione, collegamento errato o pompa di calore spenta l’elettronica di caldaia non rileva la pompa di calore -> La pompa di calore non soddisfa le richieste di riscaldamento e raffrescamento ambiente, una volta ripristinati i collegamenti è necessario spegnere e riaccendere il sistema"},
    {102, "Zone 1 off-line expansion alarm. Communication anomaly with zone 1 -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Allarme off-line espansione zona 1. Anomalia comunicazione con zona 1 -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {103, "Zone 2 off-line expansion alarm. Communication anomaly with zone 2 -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Allarme off-line espansione zona 2. Anomalia comunicazione con zona 2 -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {104, "Zone 3 off-line expansion alarm. Communication anomaly with zone 3 -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Allarme off-line espansione zona 3. Anomalia comunicazione con zona 3 -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {106, "DHW probe alarm. The board detects an anomaly on the storage tank probe -> The system cannot produce domestic hot water with the heat pump. The production of the domestic hot water is guaranteed by the boiler",
         "Allarme sonda sanitario. La scheda rileva un’anomalia sulla sonda boiler -> Il sistema non può produrre acqua calda sanitaria con la pompa di calore. La produzione dell’acqua calda sanitaria viene garantita dalla caldaia"},
    {120, "Zone 1 dehumidification high set alarm. The cooling flow set calculated for dehumidification exceeds the limit set in zone 1 -> The calculated flow set exceeds the limit permitted by the dehumidifier. Cool the room and wait until the dew temperature returns to acceptable values",
         "Allarme set elevato per deumidificazione zona 1. Il set di mandata raffreddamento calcolato per la deumidifica è superiore al limite impostato nella zona 1 -> Il set di mandata calcolato è superiore al limite ammesso dal deumidificatore. Raffrescare l'ambiente ed attendere che la temperatura di rugiada torni a valori accettabili"},
    {121, "Zone 1 device offline alarm. Communication with the zone control is not detected. It is not possible to perform the zone temperature control -> Check that the remote control is switched on",
         "Allarme offline dispositivo di zona 1. Non viene rilevata la comunicazione con il controllo di zona. Non è possibile effettuare la termoregolazione della zona -> Verificare che il controllo remoto sia acceso"},
    {122, "Zone 2 device offline alarm. Communication with the zone control is not detected. It is not possible to perform the zone temperature control -> Check that the remote control is switched on",
         "Allarme offline dispositivo di zona 2. Non viene rilevata la comunicazione con il controllo di zona. Non è possibile effettuare la termoregolazione della zona -> Verificare che il controllo remoto sia acceso"},
    {123, "Zone 3 device offline alarm. Communication with the zone control is not detected. It is not possible to perform the zone temperature control -> Check that the remote control is switched on",
         "Allarme offline dispositivo di zona 3. Non viene rilevata la comunicazione con il controllo di zona. Non è possibile effettuare la termoregolazione della zona -> Verificare che il controllo remoto sia acceso"},
    {125, "Zone 1 room temperature probe anomaly. Anomaly on the room temperature probe of zone 1 (optional). It is not possible to perform the zone temperature control -> In addition to the temperature, the dew point is not calculated for the zone either",
         "Anomalia sonda temperatura ambiente zona 1. Anomalia presente sulla sonda temperatura ambiente zona 1 (optional). Non è possibile effettuare la termoregolazione della zona -> Oltre alla temperatura non viene calcolato il punto di rugiada per la zona"},
    {126, "Zone 2 room temperature probe anomaly. Anomaly on the room temperature probe of zone 2 (optional.) It is not possible to perform the zone temperature control -> In addition to the temperature, the dew point is not calculated for the zone either",
         "Anomalia sonda temperatura ambiente zona 2. Anomalia presente sulla sonda temperatura ambiente zona 2 (optional). Non è possibile effettuare la termoregolazione della zona -> Oltre alla temperatura non viene calcolato il punto di rugiada per la zona"},
    {127, "Zone 3 room temperature probe anomaly. Anomaly on the room temperature probe of zone 3 (optional). It is not possible to perform the zone temperature control -> In addition to the temperature, the dew point is not calculated for the zone either",
         "Anomalia sonda temperatura ambiente zona 3. Anomalia presente sulla sonda temperatura ambiente zona 3 (optional). Non è possibile effettuare la termoregolazione della zona -> Oltre alla temperatura non viene calcolato il punto di rugiada per la zona"},
    {129, "Zone 1 humidity probe anomaly. Anomaly on the humidity probe of zone 1 (optional). Zone humidity cannot be checked -> In addition to the humidity, the dew point is not calculated for the zone either",
         "Anomalia sonda umidità zona 1. Anomalia presente sulla sonda umidità zona 1 (optional). Non è possibile effettuare il controllo dell’umidità della zona -> Oltre all’umidità non viene calcolato il punto di rugiada per la zona"},
    {130, "Zone 2 humidity probe anomaly. Anomaly on the zone 2 humidity probe (optional). Zone humidity cannot be checked -> In addition to the humidity, the dew point is not calculated for the zone either",
         "Anomalia sonda umidità zona 2. Anomalia presente sulla sonda umidità zona 2 (optional). Non è possibile effettuare il controllo dell’umidità della zona -> Oltre all’umidità non viene calcolato il punto di rugiada per la zona"},
    {131, "Zone 3 humidity probe anomaly. Anomaly on the zone 3 humidity probe (optional). Zone humidity cannot be checked -> In addition to the humidity, the dew point is not calculated for the zone either",
         "Anomalia sonda umidità zona 3. Anomalia presente sulla sonda umidità zona 3 (optional). Non è possibile effettuare il controllo dell’umidità della zona -> Oltre all’umidità non viene calcolato il punto di rugiada per la zona"},
    {132, "Zone 2 dehumidification high set alarm. The cooling flow set calculated for dehumidification exceeds the limit set in zone 2 -> The calculated flow set exceeds the limit permitted by the dehumidifier. Cool the room and wait until the dew temperature returns to acceptable values",
         "Allarme set elevato per deumidifica zona 2. Il set di mandata raffreddamento calcolato per la deumidifica è superiore al limite impostato nella zona 2 -> Il set di mandata calcolato è superiore al limite ammesso dal deumidificatore. Raffrescare l'ambiente ed attendere che la temperatura di rugiada torni a valori accettabili"},
    {133, "Zone 1 dehumidifier fault alarm. Anomaly coming from the dehumidifier (optional) in zone 1 -> The system does not dehumidify in the relative zone",
         "Allarme guasto deumidificatore zona 1. Anomalia proveniente dal deumidificatore (optional) sulla zona 1 -> Il sistema non effettua la deumidificazione nella relativa zona"},
    {134, "Zone 2 dehumidifier fault alarm. Anomaly coming from the dehumidifier (optional) in zone 2 -> The system does not dehumidify in the relative zone",
         "Allarme guasto deumidificatore zona 2. Anomalia proveniente dal deumidificatore (optional) sulla zona 2 -> Il sistema non effettua la deumidificazione nella relativa zona"},
    {135, "Zone 3 dehumidifier fault alarm. Anomaly coming from the dehumidifier (optional) in zone 3 -> The system does not dehumidify in the relative zone",
         "Allarme guasto deumidificatore zona 3. Anomalia proveniente dal deumidificatore (optional) sulla zona 3 -> Il sistema non effettua la deumidificazione nella relativa zona"},
    {137, "Reset system alarm – Restart the system. When the default parameters are restored, the system needs to be restarted -> Turn the system off and on",
         "Allarme sistema ripristinato – Riavviare il sistema. Ad avvenuto ripristino dei parametri di default il sistema necessita di un riavvio -> Spegnere e accendere il sistema"},
    {138, "Screed heater in progress",
         "Scaldamassetto in corso"},
    {139, "Deaeration in progress",
         "Disareazione in corso"},
    {177, "DHW maximum time alarm. The domestic hot water production requirements are not met within the preset time (5 hours) -> The system continues to operate with non-optimal performance",
         "Allarme tempo massimo sanitario. Non viene soddisfatta la produzione di acqua calda sanitaria nel tempo prestabilito (5 ore) -> il sistema continua a funzionare con prestazioni non ottimali"},
    {178, "Anti-legionella cycle not successful. The anti-legionella cycle is performed unsuccessfully within the preset time (3 hours) -> Press the Reset button",
         "Ciclo di antilegionella senza successo. Il ciclo antilegionella viene eseguito senza successo entro il tempo prestabilito (3 ore) -> Premere il pulsante di Reset"},
    {179, "Liquid probe anomaly. The board detects an anomaly on the liquid phase probe -> The system does not start. Call an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Anomalia sonda liquida. La scheda rileva un’anomalia sulla sonda fase liquida -> Il sistema non parte. Chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {181, "Remote Control communication failure zone 2. This happens when an incompatible remote control is connected or when communication between the hydronic module and the CARV2 of the second zone is lost -> Disconnect and reconnect the power to the hydronic module. If the Remote Control is still not detected at restart, the system will switch to local operating mode, i.e. using the controls on the control panel. In this case the “Central Heating”, function cannot be activated",
         "Perdita comunicazione Comando Remoto zona 2. Si verifica nel caso di collegamento a un controllo remoto non compatibile, oppure in caso di caduta di comunicazione fra modulo idronico e CARV2 della seconda zona -> Togliere e ridare tensione al modulo idronico. Se alla riaccensione non viene rilevato il Comando Remoto il sistema passa in modalità di funzionamento locale quindi utilizzando i comandi presenti sul pannello comandi. In questo caso non è possibile attivare la funzione “Riscaldamento”"},
    {182, "Condensing unit alarm. An anomaly is signalled on the condensing unit -> The system does not work, see the anomaly on the condensing unit and its instructions booklet",
         "Allarme motocondensante. Viene segnalata un’anomalia sulla motocondensante -> Il sistema non funziona, vedi anomalia sulla motocondensante e relativo libretto istruzioni"},
    {183, "Condensing unit alarm in test mode. A signal notifies that the condensing unit is in test mode -> During this time, room heating/air conditioning and domestic hot water production requirements cannot be met",
         "Allarme motocondensante in testmode. Viene segnalato che la motocondensante è in fase test mode -> Durante questa fase non è possibile soddisfare le richieste di climatizzazione ambiente e produzione acqua calda sanitaria"},
    {184, "Communication with outdoor unit timeout alarm. A signal notifies an anomaly due to a communication problem between the indoor unit and the condensing unit -> Have the electrical connection between the units checked",
         "Allarme timeout comunicazione con unità esterna. Viene segnalata l’anomalia per un problema di comunicazione tra unità interna e motocondensante -> Far verificare il collegamento elettrico tra le unità"},
    {185, "Safety module communication alarm. Communication anomaly between P.C.B. and ignition board -> Have the electrical connection between the components checked",
         "Allarme comunicazione safety module. Problema nella comunicazione tra scheda regolazione e scheda accensione -> Far verificare il collegamento tra i componenti"},
    {186, "Igniter high voltage anomaly. An anomaly appears on the ignition board -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Anomalia alta tensione accenditore. Viene segnalata un’anomalia sulla scheda accensione -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {187, "Condensing unit return probe alarm. The board detects an anomaly on the heat pump return NTC probe -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Allarme sonda ritorno motocondensante. La scheda rileva un’anomalia sulla sonda NTC di ritorno pompa dicalore -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {188, "Request out of operating range. A heating or cooling request is made with an outdoor temperature exceeding the operating limits -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Richiesta fuori dal range di funzionamento. Viene fatta una richiesta riscaldamento o raffrescamento con temperatura esterna al di fuori dei limiti di funzionamento -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {189, "Communication with communication board timeout alarm. If communication between the printed circuit boards is lost, an anomaly is signalled -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Allarme timeout comunicazione con scheda comunicazione. In caso di caduta di comunicazione tra le schede elettroniche viene segnalata l’anomalia -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {191, "RF communication failure towards CAR v2 RF zone 2. If there is no communication between the indoor unit and Wireless version CAR of the second zone, an anomaly is signalled. From this moment onwards, it is only possible to control the system by means of the indoor unit control panel -> Check operation of the Wireless CAR, check the battery charge (refer to the relative instructions booklet)",
         "Caduta comunicazione RF verso CAR v2 RF zona 2. In caso di caduta di comunicazione tra unità interna e CAR versione Wireless della seconda zona viene segnalata l’anomalia, da questo momento è possibile controllare il sistema unicamente attraverso il pannello comandi dell’unità interna stessa -> Verificare il funzionamento del CAR Wireless, verificare la carica delle batterie (vedere il relativo libretto istruzioni)"},
    {192, "Condensing unit flow probe anomaly. The board detects an anomaly on the NTC heat pump flow probe -> If the block or anomaly persists, contact an authorised company (e.g. Immergas Technical After-Sales Service).",
         "Anomalia sonda mandata motocondensante. La scheda rileva un’anomalia sulla sonda NTC mandata pompa di calore -> Se il blocco o l'anomalia persiste e' necessario chiamare una impresa abilitata (ad esempio il Servizio Assistenza Tecnica Immergas)."},
    {193, "Appliance in Test mode. A signal notifies that the appliance is in test mode -> The system continues operating properly",
         "Apparecchio in Testmode. Viene segnalato che l’apparecchio è in fase test mode -> Il sistema continua a funzionare correttamente"},
    {194, "Audax Pro disabled. A signal notifies that the condensing unit has been disabled through the appropriate input in the terminal board -> The system continues operating properly",
         "Audax Pro disabilitata. Viene segnalato che la motocondensante è stata disabilitata tramite l’apposito ingresso in morsettiera -> Il sistema continua a funzionare correttamente"},
    {195, "Liquid phase low temp. anomaly. An excessively low temperature is detected in the liquid phase -> Check that the cooling circuit is working properly",
         "Anomalia bassa temp. fase liquida. Viene rilevata una temperatura troppo bassa nella fase liquida -> Verificare il buon funzionamento del circuito frigorifero"},
    {196, "High flow temp. block. An excessively high temperature is detected on the heat pump flow circuit -> Check that the cooling circuit is working properly",
         "Blocco temp. mandata elevata. Viene rilevata una temperatura troppo elevata sul circuito di mandata della pompa di calore -> Verificare il buon funzionamento del circuito frigorifero"},
};

static const char *const DEFAULT_EN = "General unrecognised anomaly";
static const char *const DEFAULT_IT = "Anomalia generica non riconosciuta -> Verificare tabella errori o scheda selezionata";
static const size_t MAX_LEN = 250;  // bytes; HA rejects states longer than 255 characters

// Cut s to at most n bytes at a word boundary, never inside a UTF-8 sequence.
inline std::string cut_words(const std::string &s, size_t n) {
  if (s.size() <= n) return s;
  size_t cut = s.rfind(' ', n);
  if (cut == std::string::npos || cut < n / 2) {
    cut = n;
    while (cut > 0 && (static_cast<unsigned char>(s[cut]) & 0xC0) == 0x80) cut--;
  }
  return s.substr(0, cut);
}

// Keep title and action; shorten the description in the middle when the text is too long.
inline std::string fit(const char *text) {
  std::string s(text);
  if (s.size() <= MAX_LEN) return s;
  static const char *const ARROW = " -> ";
  size_t a = s.rfind(ARROW);
  if (a != std::string::npos) {
    std::string action = s.substr(a);  // " -> action"
    if (action.size() + 40 < MAX_LEN) {
      return cut_words(s.substr(0, a), MAX_LEN - action.size() - 3) + "..." + action;
    }
  }
  return cut_words(s, MAX_LEN - 3) + "...";
}

inline const char *raw(int code, bool italian) {
  for (const Entry &e : TABLE) {
    if (e.code == code) return italian ? e.it : e.en;
  }
  return italian ? DEFAULT_IT : DEFAULT_EN;
}

// State for the "Boiler fault (description)" text sensor.
inline std::string describe(int code, bool italian) {
  if (code == 0) return italian ? "Nessuna anomalia" : "No faults";
  return fit(raw(code, italian));
}

}  // namespace faults
